{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Little Things \u8212- Launchpad Chop Engine\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Transforma qualquer trecho da timeline do REAPER em um kit pronto para tocar no {\b Novation Launchpad (MK3)}: captura o \u225 ?udio, fatia e distribui as fatias nos pads, com as cores acesas no pr\u243 ?prio Launchpad.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Recursos\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Envia o trecho selecionado da timeline para o pad escolhido\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Fatia em 8, 16, 32 ou 64 pads\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Modos Gate, One-Shot e Loop, com choke groups\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Reprodu\u231 ?\u227 ?o via RS5K, configurada automaticamente\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Salvar e carregar kits ({\f1 .ltkit})\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab LEDs do Launchpad sincronizados em tempo real\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Requisitos\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\field{\*\fldinst{HYPERLINK "https://github.com/cfillion/reaimgui"}}{\fldrslt{\ul
ReaImGui
}}}
 (via ReaPack)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Novation Launchpad MK3 (opcional, para tocar no hardware)\sa180\par}
}
